using Microsoft.AspNetCore.DataProtection;
using System.Security.Cryptography;
using System.Text.Json;
namespace HomeLibrary;
// Capability secret is in the URL fragment (not server request URLs), then a
// Bearer header. It grants only one reader's list; never a paired-phone role.
public sealed class ReadingAccess {
 readonly object gate=new();readonly string file;readonly string origin;readonly IDataProtector protector;Dictionary<string,string> tokens;
 public ReadingAccess(string directory,string origin,IDataProtectionProvider provider){this.origin=origin.TrimEnd('/');file=Path.Combine(directory,"reading-access.protected");protector=provider.CreateProtector("HomeLibrary.ReadingAccess.v1");tokens=File.Exists(file)?JsonSerializer.Deserialize<Dictionary<string,string>>(protector.Unprotect(File.ReadAllBytes(file)),Library.Json)??new():new();}
 public string? Resolve(string token){lock(gate){if(origin==""||token.Length!=43)return null;var supplied=System.Text.Encoding.ASCII.GetBytes(token);return tokens.FirstOrDefault(x=>CryptographicOperations.FixedTimeEquals(supplied,System.Text.Encoding.ASCII.GetBytes(x.Value))).Key;}}
 public object Status(string readerId){lock(gate)return new{configured=origin!="",enabled=origin!=""&&tokens.ContainsKey(readerId),url=origin!=""&&tokens.TryGetValue(readerId,out var token)?origin+"/reading/#"+token:""};}
 public object Change(string readerId,string action){lock(gate){if(action is not ("enable" or "replace" or "disable"))throw new LibraryError("Unknown personal-link action.");if(action!="disable"&&origin=="")throw new LibraryError("Configure public HTTPS sharing first, then create a personal reading link.");var next=new Dictionary<string,string>(tokens);if(action=="disable")next.Remove(readerId);else if(action=="replace"||!next.ContainsKey(readerId))next[readerId]=Convert.ToBase64String(RandomNumberGenerator.GetBytes(32)).TrimEnd('=').Replace('+','-').Replace('/','_');File.WriteAllBytes(file+".tmp",protector.Protect(JsonSerializer.SerializeToUtf8Bytes(next,Library.Json)));if(!OperatingSystem.IsWindows())File.SetUnixFileMode(file+".tmp",UnixFileMode.UserRead|UnixFileMode.UserWrite);File.Move(file+".tmp",file,true);tokens=next;return Status(readerId);}}
 public static object View(Snapshot snapshot,string readerId,bool includeLoans=false){var s=snapshot.State;var reader=s.Readers.Find(r=>r.Id==readerId)??throw new LibraryError("Personal reading link is unavailable.",401);var loans=includeLoans?s.Loans.Where(l=>l.BorrowerId==reader.BorrowerId).ToArray():[];var own=s.ReadingEntries.Where(e=>e.ReaderId==readerId).ToArray();return new{revision=snapshot.Revision,libraryName=s.LibraryName,readerName=reader.Name,contact=s.Borrowers.Find(b=>b.Id==reader.BorrowerId)?.Contact??"",entries=own.Select(e=>new{e.CopyId,e.Status,e.StartedDate,e.FinishedDate,e.Rating,e.Notes}),books=s.Books.Where(b=>!b.Archived||own.Any(e=>e.CopyId==b.Id)||loans.Any(l=>l.CopyId==b.Id)||s.Requests.Any(r=>r.ReaderId==readerId&&r.CopyId==b.Id)).Select(b=>new{b.Id,b.Isbn,b.Title,b.Description,b.Author,b.CoverUrl,b.Archived,availability=CirculationPolicy.Availability(s,b.Id)}),loans=loans.Select(l=>new{l.CopyId,l.CheckoutDate,l.DueDate,l.ReturnedDate}),requests=s.Requests.Where(r=>r.ReaderId==readerId).Select(r=>new{r.Id,r.CopyId,status=r.Status=="fulfilled"&&s.Loans.Any(l=>l.Id==r.LoanId&&l.ReturnedDate!=null)?"returned":r.Status,holdStage=s.Holds.Find(h=>h.RequestId==r.Id)?.Stage??""})};}
}
